sparql_response:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Romance_on_the_Run dbr:The_Palace_of_Angels }

  # director (prefer dbp, fallback to dbo)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL {
    FILTER NOT EXISTS { ?film dbp:director ?director . }
    ?film dbo:director ?director .
  }

  # director birth date (prefer dbp, fallback to dbo)
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL {
    FILTER NOT EXISTS { ?director dbp:birthDate ?birthDate . }
    ?director dbo:birthDate ?birthDate .
  }

  # readable labels
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
}
LIMIT 100

